xml.Script:
        Color[0] := 'EE0000'; // Red
        Color[1] := 'FF6600'; // Orange
        Color[2] := '0033EE'; // Blue
        Color[3] := '00BB00'; // Green
        Color[4] := 'FFEE00'; // Yellow
        Color[5] := 'FFFFFF'; // White

        W := 0.2;
        include 'Figures\Scripts\Cube_Coordinates.inc';

        R := W * 4.0;
        H := W * 2 / 3;
        D := W / 3;
        L := 4 * D; // Length of cutting area

        R0 := R - (L * sqrt(3) - (2 * W - L)) / sqrt(2); // center of cuboid

        sAngle := 2 * Pi / 3;
        for i := 0 to 2 do begin
            x[i] := -R * sin(sAngle * i);
            y[i] := -R * cos(sAngle * i);
            x1[i] := R/2 * sin(sAngle * i);
            y1[i] := R/2 * cos(sAngle * i);
        end;

        A0 := 0;
        A1 := 2*Pi / 3;
        A2 :=-2*Pi / 3;

        B1 :=-Pi/4;
        B2 := Pi/4;

